def plus_own(r,c):
    """The 5 cells (center plus 4 orthogonal neighbors) of a diamond centered at (r,c)."""
    return {(r-1,c),(r+1,c),(r,c-1),(r,c+1),(r,c)}

def beam(grid,r,c,dr,dc,color,own,overwrite=False):
    """From (r,c) step in one direction writing color on eligible cells, stopping at a 3 not in own."""
    H,W=len(grid),len(grid[0]); r,c=r+dr,c+dc
    while 0<=r<H and 0<=c<W:
        if grid[r][c]==3 and (r,c) not in own: return grid
        if grid[r][c]==0 or (overwrite and grid[r][c]!=3): grid[r][c]=color
        r,c=r+dr,c+dc
    return grid

